            request, risk_occupancy, "SETTLEMENT_EXCEEDS_AVAILABLE_BALANCE"
        )
    if risk_occupancy > request.base_limit:
        return self._build_rejected(
            request, risk_occupancy, "RISK_OCCUPANCY_EXCEEDS_BASE_LIMIT"
        )
    if (
        group_id is not None
